const trigger = $('Telegram Message Trigger').first().json;

// универсальный рекурсивный поиск по ключу
function findObject(obj, keyName) {
  if (!obj || typeof obj !== 'object') return null;

  if (obj[keyName]) {
    return obj[keyName];
  }

  for (const key of Object.keys(obj)) {
    const result = findObject(obj[key], keyName);
    if (result) return result;
  }

  return null;
}

const chat = findObject(trigger, "chat");
const from = findObject(trigger, "from");

return [
  {
    json: {
      chat_id: chat?.id,
      chat_type: chat?.type,
      user_id: from?.id,
      username: from?.username,
      fist_name: from?.first_name,
      text: trigger?.message?.text ?? null,
      message_id: trigger?.message?.message_id ?? trigger?.callback_query.message.message_id 
    }
  }
];

// Получаем все кнопки из исходного сообщения
const buttons = $('Telegram Message Trigger')
  .first()
  .json
  .callback_query
  .message
  .reply_markup
  .inline_keyboard
  .flat();

// Получаем сырые данные из нажатой кнопки (например, "approve_idea:uuid-123:done")
const rawCallbackData = $('Telegram Message Trigger').first().json.callback_query.data;

// Разбиваем строку по разделителю ':'
const parts = rawCallbackData.split(':');

// Присваиваем части переменным
const callback_type = parts[0];
const targetValue = parts.length === 3 ? parts[2] : parts[1];
const targetOptionalValue = parts.length === 3 ? parts[1] : null; // Если третьей части нет, будет null

// Ищем текст нажатой кнопки
let text;

for (const btn of buttons) {
  // Пропускаем кнопки без callback_data (например, URL-кнопки)
  if (!btn.callback_data) continue;

  // Разбиваем callback_data каждой кнопки в цикле
  const btnParts = btn.callback_data.split(':');
  const btnValue = btnParts[1];
  const btnOptionalValue = btnParts[2] || null;

  // Сравниваем данные, чтобы найти нужную кнопку
  if (targetOptionalValue) {
    // Если в нажатой кнопке был optional_value, сравниваем все части
    if (btnValue === targetValue && btnOptionalValue === targetOptionalValue) {
      text = btn.text;
      break;
    }
  } else {
    // Если optional_value не было, ищем кнопку, где его тоже нет
    if (btnValue === targetValue && !btnOptionalValue) {
      text = btn.text;
      break;
    }
  }
}

return [{
  json: {
    callback_type,
    value: targetValue,
    optional_value: targetOptionalValue,
    text
  }
}];

