const tankVolume = parseFloat(state.tank_volume_litres);

const isValid = !isNaN(volume) && volume > 0 && volume <= tankVolume * 2;
return [{
  json: {
    ...$json,
    volume: isValid ? volume : null,
    is_valid: isValid,
    generator_id: state.generator_id,
    generator_name: state.generator_name,
    tank_volume_litres: tankVolume
  }
}];

