const generators = $input.all().map(item => item.json);
if (generators.length === 0) {
  return [{ json: { text: "❌ Для вашої локації не знайдено активних генераторів." } }];
}

const locationName = generators[0].location_name;
let text = `📍 <b>${locationName}</b>\n\n`;

for (const gen of generators) {
  const hoursService = parseFloat(gen.hours_since_last_service) || 0;
  const interval = parseFloat(gen.maintenance_interval_hours) || 50;
  const servicePct = Math.min(Math.round((hoursService / interval) * 100), 100);

  const currentFuel = parseFloat(gen.current_fuel_litres) || 0;
  const tankVolume = parseFloat(gen.tank_volume_litres) || 0;
  const fuelPct = tankVolume > 0 ? Math.min(Math.round((currentFuel / tankVolume) * 100), 100) : 0;

  const consumption = parseFloat(gen.consumption_per_hour) || 0;
  const hoursLeft = consumption > 0 ? Math.round((currentFuel / consumption) * 10) / 10 : 0;

  const statusEmoji = gen.status === 'critical' ? '🔴' : gen.status === 'warning' ? '🟡' : '🟢';

  text += `⚙️ <b>${gen.generator_name}</b>\n`;
  text += `${statusEmoji} ТО: ${hoursService}/${interval} год (${servicePct}%)\n`;
  text += `⛽ Паливо: ${currentFuel} л (${fuelPct}%) — ~${hoursLeft} год роботи\n\n`;
}

return [{ json: { text: text.trim() } }];

