const text = $('Parser tg trigger').first().json.text || '';
let invite_code = null;

// Якщо користувач перейшов за посиланням або ввів /start КОД
if (text.startsWith('/start ')) {
  invite_code = text.split(' ')[1].trim();
} 
// Або якщо він просто скопіював і відправив сам код текстом
else if (!text.startsWith('/') && text.trim().length > 0) {
  invite_code = text.trim();
}

return {
  ...$input.item.json,
  invite_code: invite_code
};

